-- V1_033 : Remplacement des presets esthetiques (MINIMAL/MODERN/CORPORATE/COLORFUL/DARK)
-- par des presets fonctionnels par type d'action email.
-- Prerequis : V1_032 applique.

-- ─── Etape 1 : Etendre l'ENUM pour inclure les nouvelles categories fonctionnelles ───────────
ALTER TABLE email_template_preset
    MODIFY COLUMN category ENUM(
        'MINIMAL', 'MODERN', 'CORPORATE', 'COLORFUL', 'DARK',
        'APPLICATION_VERIFICATION', 'PASSWORD_RESET', 'INVITATION_CODE',
        'CANDIDATE_ASK_RESULT', 'PRE_SCREEN_DECISION', 'FINAL_DECISION',
        'INTERVIEW_INVITE', 'QUIZ_INVITE', 'WELCOME', 'GENERIC'
    ) NOT NULL DEFAULT 'GENERIC';

-- ─── Etape 2 : Supprimer (soft-delete) tous les presets existants ─────────────────────────────
UPDATE email_template_preset SET is_deleted = TRUE;

-- ─── Etape 3 : Inserer les 10 nouveaux presets fonctionnels ──────────────────────────────────

-- ────────────────────────────────────────────────────────────────────────────────────────────
-- 3.1  GENERIC — Layout polyvalent, toutes sections presentes
-- ────────────────────────────────────────────────────────────────────────────────────────────
INSERT INTO email_template_preset (name, category, html_structure, description, is_deleted, created_at, updated_at) VALUES (
'Email generique',
'GENERIC',
'<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><style>body{margin:0;padding:0;background-color:#f1f5f9;font-family:Arial,''Segoe UI'',sans-serif}.bd p{margin:0 0 14px 0}@media only screen and (max-width:480px){.rp{padding-left:20px !important;padding-right:20px !important}.t1{font-size:22px !important}}</style></head><body><table width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#f1f5f9"><tr><td style="padding:32px 16px"><table width="600" align="center" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;margin:0 auto;background-color:#ffffff;border:1px solid #e2e8f0"><tr><td bgcolor="{{primaryColor}}" height="5" style="background-color:{{primaryColor}};height:5px;font-size:0;line-height:5px">&nbsp;</td></tr><tr><td class="rp" style="padding:28px 36px 20px"><p style="margin:0 0 12px;font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:{{primaryColor}}">{{companyName}}</p><p class="t1" style="margin:0 0 8px;font-size:26px;font-weight:700;line-height:1.2;color:#1e293b">{{title}}</p><p style="margin:0;font-size:15px;line-height:1.6;color:#64748b">{{subtitle}}</p></td></tr><tr><td style="padding:0 36px"><table width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td style="border-top:1px solid #e2e8f0;font-size:0;line-height:0">&nbsp;</td></tr></table></td></tr><tr><td class="rp bd" style="padding:24px 36px;font-size:15px;line-height:1.75;color:#334155">{{content}}</td></tr><tr><td class="rp" style="padding:4px 36px 28px"><a href="{{buttonLink}}" style="display:inline-block;padding:13px 26px;background-color:{{primaryColor}};color:#ffffff;text-decoration:none;font-weight:700;border-radius:6px;font-size:15px">{{buttonText}}</a></td></tr><tr><td class="rp" style="padding:20px 36px;font-size:14px;line-height:1.7;color:#64748b;border-top:1px solid #e2e8f0">{{signature}}</td></tr><tr><td class="rp" style="padding:18px 36px;background-color:#f8fafc;font-size:12px;color:#94a3b8;text-align:center;border-top:1px solid #e2e8f0;line-height:1.6">{{companyName}} &mdash; {{companyAddress}}<br>&copy; {{currentYear}}</td></tr></table></td></tr></table></body></html>',
'Layout polyvalent et neutre, utilisable pour tout type de communication email.',
FALSE, NOW(), NOW()
);

