s="rp bd" style="padding:24px 36px;font-size:15px;line-height:1.75;color:#334155">{{content}}</td></tr><tr><td class="rp" style="padding:4px 36px 28px;text-align:center"><a href="{{buttonLink}}" style="display:inline-block;padding:15px 32px;background-color:{{primaryColor}};color:#ffffff;text-decoration:none;font-weight:700;border-radius:8px;font-size:16px">{{buttonText}}</a></td></tr><tr><td class="rp" style="padding:20px 36px;font-size:14px;line-height:1.7;color:#64748b;border-top:1px solid #e2e8f0">{{signature}}</td></tr><tr><td class="rp" style="padding:18px 36px;background-color:#f8fafc;font-size:12px;color:#94a3b8;text-align:center;border-top:1px solid #e2e8f0;line-height:1.6">{{companyName}} &mdash; {{companyAddress}}<br>&copy; {{currentYear}}</td></tr></table></td></tr></table></body></html>',
